function markNetworkLinks(container) {
var links = container.matches && container.matches("a[href]") ? [container] : $all("a[href]", container);
links.forEach(function (link) {
if (link.dataset.requiresNetwork) return;
var url;
try { url = new URL(link.href, location.href); } catch (error) { return; }
if (!/^https?:$/.test(url.protocol) || url.origin === location.origin || url.hostname === "maps.apple.com") return;
link.dataset.requiresNetwork = "true";
var hint = document.createElement("span");
hint.className = "network-required";
hint.title = "wymaga sieci";
hint.setAttribute("aria-label", "wymaga sieci");
hint.textContent = " ↗";
link.appendChild(hint);
});
}
markNetworkLinks(document);
new MutationObserver(function (records) {
records.forEach(function (record) {
record.addedNodes.forEach(function (node) { if (node.nodeType === 1) markNetworkLinks(node); });
});
}).observe(document.body, {childList:true, subtree:true});
var todayKicker = $("[data-today-kicker]");
var todayTitle = $("[data-today-title]");
var todayBody = $("[data-today-body]");
var todayActions = $("[data-today-actions]");
function updateTodayMarkup(target, html) {
if (!target || target.innerHTML === html) return;
var template = document.createElement("template");
template.innerHTML = html;
function sync(parent, desired) {
Array.prototype.slice.call(desired.childNodes).forEach(function (next, index) {
var old = parent.childNodes[index];
if (!old) { parent.appendChild(next.cloneNode(true)); return; }
if (old.nodeType !== next.nodeType || old.nodeName !== next.nodeName) {
parent.replaceChild(next.cloneNode(true), old);
} else if (old.nodeType === 3) {
if (old.nodeValue !== next.nodeValue) old.nodeValue = next.nodeValue;
} else if (old.nodeType === 1) {
Array.prototype.slice.call(old.attributes).forEach(function (attr) {
if (!next.hasAttribute(attr.name)) old.removeAttribute(attr.name);
});
Array.prototype.slice.call(next.attributes).forEach(function (attr) {
if (old.getAttribute(attr.name) !== attr.value) old.setAttribute(attr.name, attr.value);
});
sync(old, next);
}
});
while (parent.childNodes.length > desired.childNodes.length) parent.lastChild.remove();
}
sync(target, template.content);
markNetworkLinks(target);
}
